<script setup lang="ts">
import type { MapState, MapFeature, GeoShape, CommunityRecord, UseData } from '~/types/community'
import type { PointDto, PointDetailDto, CommunityDto } from '~/types/api'
import { errorMessage } from '~/utils/format'
import { gridDescendants } from '~/utils/gridTree'
const route=useRoute(),router=useRouter()
const listMode=computed(()=>route.query.view==='list')
function switchMode(mode:'map'|'list'){if(!mayLeaveUse())return;void router.replace({path:'/map',query:{...route.query,view:mode==='list'?'list':undefined,place:undefined}})}
const returnTo=computed(()=>selected.value?.kind==='point'?`/map?place=${selected.value.id}`:'/map')
const { bootstrap, load: loadBootstrap } = useAppData()
const { purposes, purpose, loadPurposes } = usePurposeCatalog()
const mapState=ref<MapState>({layers:[],features:[]}),error=ref(''),query=ref(''),loading=ref(false)
const selected=ref<MapFeature|null>(null),detail=ref<PointDetailDto|null>(null),uses=ref<CommunityRecord<UseData>[]>([])
const useId=ref(''),useOpen=ref(false),inspectionId=ref(''),mobilePane=ref('place'),showEnded=ref(false)
const pending=ref<GeoShape|null>(null),saving=ref(false),editor=ref(false),editingPoint=ref<PointDto|null>(null),filterOpen=ref(false),layerOpen=ref(false),searchResults=ref(false),gridEditor=ref(false),showGridBoundaries=ref(false)
const editingGrid=ref<CommunityDto|null>(null)
const highDefinition=useState('map-high-definition',()=>false)
const loadDepth=useState<number>('community-map-depth',()=>0)
const exportOpen=ref(false), exporting=ref(false), exportError=ref('')
const exportScale=ref(2), exportPartitions=ref(2), exportMarkers=ref(true), exportGrids=ref(false), exportAll=ref(false)
const exportLayerIds=ref<string[]>([]), exportBaseSize=ref<[number,number]>([0,0])
const exportResolution=computed(()=>[exportBaseSize.value[0]*exportScale.value,exportBaseSize.value[1]*exportScale.value])
function openExport(){exportAll.value=false;exportMarkers.value=true;exportGrids.value=showGridBoundaries.value;exportLayerIds.value=mapState.value.layers.filter(x=>x.enabled).map(x=>x.id);exportBaseSize.value=canvas.value?.getExportSize()??[0,0];exportError.value='';exportOpen.value=true}
function toggleExportLayer(id:string,checked:boolean){exportLayerIds.value=checked?[...exportLayerIds.value,id]:exportLayerIds.value.filter(x=>x!==id)}
async function exportMap(){if(exporting.value)return;exporting.value=true;exportError.value='';try{await canvas.value?.exportImage({scale:Number(exportScale.value),partitions:Number(exportPartitions.value),layerIds:exportLayerIds.value,markers:exportMarkers.value,grids:exportGrids.value});exportOpen.value=false}catch(e){exportError.value=errorMessage(e)}finally{exporting.value=false}}
async function toggleLayer(layer:MapState['layers'][number],checked:boolean){const previous=layer.enabled;layer.enabled=checked;try{await $fetch('/api/map/layers',{method:'POST',body:layer,retry:0})}catch(e){layer.enabled=previous;error.value=errorMessage(e)}}
const filter=reactive(useState('community-map-filter',()=>({grid:'all',type:'all',purpose:'all',issues:false})).value)
const canvas=useTemplateRef('canvas'),usePanel=useTemplateRef('usePanel')
onBeforeRouteLeave(()=>mayLeaveUse())
const editingTarget=ref<MapFeature|null>(null),sketching=ref(false)
function mayLeaveUse(){if(usePanel.value?.busy)return false;return !usePanel.value?.dirty||window.confirm('使用情况尚未保存，放弃修改吗？')}
function closeUse(){if(mayLeaveUse()){useOpen.value=false;mobilePane.value='place'}}
function beginDrawing(){editingTarget.value=null;closePlace()}
function cancelGeometry(){canvas.value?.cancel();editingTarget.value=null}
const currentUse=computed(()=>uses.value.find(x=>x.id===useId.value)??null)
const shownUses=computed(()=>uses.value.filter(x=>showEnded.value||(!x.archived&&x.data.state!=='已结束')))
const pendingCoordinates=computed(()=>pending.value?.coordinates[0]?.join(',')??'')
const selectedGridIds=computed(()=>filter.grid==='all'?null:gridDescendants(bootstrap.value?.communities??[],filter.grid))
const boundaryTarget=computed(()=>selected.value?.kind==='grid'?selected.value.id:filter.grid==='all'?'':filter.grid)
const types=computed(()=>[{label:'全部场所形态',value:'all'},...(bootstrap.value?.pointTypes??[]).map(x=>({label:x.name,value:x.id}))])
const purposeOptions=computed(()=>[{label:'全部用途',value:'all'},...purposes.value.filter(x=>!x.archived).map(x=>({label:`${x.data.icon} ${x.name}`,value:x.id}))])
const filtered=computed(()=>mapState.value.features.filter(x=>!x.disabled&&(x.kind==='grid'?showGridBoundaries.value&&(!selectedGridIds.value||selectedGridIds.value.has(x.id)):(!selectedGridIds.value||selectedGridIds.value.has(x.communityId))&&(filter.type==='all'||x.typeId===filter.type)&&(filter.purpose==='all'||x.purposeIds?.includes(filter.purpose))&&(!filter.issues||x.openIssues>0))).filter(x=>!query.value.trim()||[x.name,...(x.uses??[]).flatMap(u=>[u.name,u.purposeName])].some(name=>name.toLowerCase().includes(query.value.trim().toLowerCase()))))
const matches=computed(()=>filtered.value.filter(x=>x.kind==='point'))
const exportFeatures=computed(()=>exportAll.value?mapState.value.features:filtered.value)
const exportPointCount=computed(()=>exportFeatures.value.filter(x=>x.kind==='point'&&!x.disabled).length)
const focusPadding=computed(()=>typeof window!=='undefined'&&window.innerWidth>=1100?[90,60,60,Math.min(window.innerWidth*.42,430)]:[Math.min(190,window.innerHeight*.23),25,Math.round(window.innerHeight*.54),25])
let selectionSequence=0
async function load(){loading.value=true;try{await Promise.all([loadBootstrap(),loadPurposes()]);mapState.value=await $fetch('/api/map')}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function choose(item:MapFeature,focus=true,confirmed=false){if(!confirmed&&!mayLeaveUse())return;void router.replace({query:{...route.query,place:item.kind==='point'?item.id:undefined}});const request=++selectionSequence;searchResults.value=false;filterOpen.value=false;selected.value=item;detail.value=null;uses.value=[];useOpen.value=false;inspectionId.value='';mobilePane.value='place';error.value='';if(focus)canvas.value?.focus(item.shape);if(item.kind!=='point')return;try{const [place,records]=await Promise.all([$fetch<PointDetailDto>(`/api/points/${item.id}`),$fetch<CommunityRecord<UseData>[]>('/api/records/use',{query:{parentId:item.id,all:true}})]);if(request!==selectionSequence)return;detail.value=place;uses.value=records;const active=records.filter(x=>!x.archived&&x.data.state!=='已结束');if(active.length===1){useId.value=active[0]!.id;useOpen.value=true}}catch(e){if(request===selectionSequence)error.value=errorMessage(e)}}
function closePlace(){if(!mayLeaveUse())return;void router.replace({query:{...route.query,place:undefined}});++selectionSequence;selected.value=null;detail.value=null;useOpen.value=false;inspectionId.value=''}
function openUse(record:CommunityRecord<UseData>|null){if(!mayLeaveUse())return;useId.value=record?.id??'';useOpen.value=true;mobilePane.value='use'}
async function useSaved(record:CommunityRecord<UseData>){if(!selected.value)return;const feature=selected.value;await load();await choose(mapState.value.features.find(x=>x.id===feature.id&&x.kind==='point')??feature,false);useId.value=record.id;useOpen.value=true;mobilePane.value='use'}
async function refreshed(){if(!selected.value)return;const feature=selected.value;const check=inspectionId.value;await load();await choose(mapState.value.features.find(x=>x.id===feature.id)??feature,false);inspectionId.value=check;mobilePane.value='inspection'}
async function saveShape(kind:string,id:string,revision:number){if(!pending.value||sketching.value)return;saving.value=true;error.value='';try{await $fetch(`/api/map/shapes/${kind}/${id}`,{method:'PUT',body:{shape:pending.value,revision},retry:0});cancelGeometry();await load();const feature=mapState.value.features.find(x=>x.kind===kind&&x.id===id);if(feature)await choose(feature,false)}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
function newPlace(){editingPoint.value=null;editor.value=true}
async function created(point:PointDto){cancelGeometry();await load();const feature=mapState.value.features.find(x=>x.kind==='point'&&x.id===point.id);if(feature)await choose(feature)}
function editShape(){if(selected.value&&mayLeaveUse()){editingTarget.value=selected.value;canvas.value?.edit(selected.value.shape);useOpen.value=false;inspectionId.value=''}}
function gridChanged(){closePlace();const feature=mapState.value.features.find(x=>x.kind==='grid'&&x.id===filter.grid);if(feature&&!pending.value)canvas.value?.focus(feature.shape)}
async function gridCreated(grid:{id:string}){cancelGeometry();await load();filter.grid=grid.id;showGridBoundaries.value=true;gridChanged()}
async function editFeature(item:MapFeature){if(!mayLeaveUse())return;await choose(item,false,true);editingTarget.value=item;if(item.kind==='grid'){filter.grid=item.id;showGridBoundaries.value=true}canvas.value?.edit(item.shape)}
async function refreshMapFeatures(){if(pending.value)return;try{const [state]=await Promise.all([$fetch<MapState>('/api/map'),loadPurposes()]);mapState.value.features=state.features}catch(e){error.value=errorMessage(e)}}
function openFilters(){filterOpen.value=!filterOpen.value;if(filterOpen.value){layerOpen.value=false;void refreshMapFeatures()}}
function openLayers(){layerOpen.value=!layerOpen.value;if(layerOpen.value)filterOpen.value=false}
function selectPurpose(id:string){filter.purpose=id;void refreshMapFeatures()}
function onMapReturn(){if(document.visibilityState==='visible')void refreshMapFeatures()}
onMounted(()=>{void load().then(()=>{const item=mapState.value.features.find(x=>x.kind==='point'&&x.id===route.query.place);if(item)void choose(item)});document.addEventListener('visibilitychange',onMapReturn);window.addEventListener('focus',onMapReturn)})
onBeforeUnmount(()=>{document.removeEventListener('visibilitychange',onMapReturn);window.removeEventListener('focus',onMapReturn)})
useHead({title:'社区地图'})
</script>
<template>
  <PointsList v-if="listMode" embedded @view-map="switchMode('map')" />
  <div v-else class="community-map" :class="{'panes-open':selected&&!pending}" data-testid="map-workspace">
    <OfflineMap ref="canvas" v-model="pending" :features="filtered" :layers="mapState.layers" :selected-id="selected?.id" :focus-padding="focusPadding" immersive :high-definition="highDefinition" :load-depth="loadDepth" :export-features="exportFeatures" height="100%" @choose="choose" @edit="editFeature" @begin="beginDrawing" @sketching="sketching=$event" :editable="!usePanel?.dirty && !usePanel?.busy" />
    <div class="map-search floating"><div class="flex gap-2"><UInput v-model="query" @update:model-value="searchResults=true" placeholder="搜索场所、店名或用途" icon="i-lucide-search" class="min-w-0 flex-1" /><UButton icon="i-lucide-list-filter" aria-label="筛选地图" color="neutral" :variant="filterOpen?'solid':'outline'" @click="openFilters" /><UButton icon="i-lucide-layers" aria-label="图层显示" color="neutral" :variant="layerOpen?'solid':'outline'" @click="openLayers" /><UButton icon="i-lucide-list" aria-label="列表模式" color="neutral" variant="outline" @click="switchMode('list')" /></div><div v-if="filterOpen" class="space-y-3 mt-3"><div class="flex gap-1 flex-wrap"><UButton v-for="item in types" :key="item.value" :label="item.label" size="sm" :variant="filter.type===item.value?'solid':'ghost'" @click="filter.type=item.value" /></div><div class="flex gap-1 flex-wrap"><UButton v-for="item in purposeOptions" :key="item.value" :label="item.label" size="sm" :variant="filter.purpose===item.value?'solid':'ghost'" @click="selectPurpose(item.value)" /></div><UButton label="仅有未完成问题" size="sm" :variant="filter.issues?'solid':'outline'" @click="filter.issues=!filter.issues" /><div class="flex justify-between text-sm text-muted"><span>{{ matches.length }} 个场所</span><button @click="Object.assign(filter,{type:'all',purpose:'all',issues:false});query=''">清空筛选</button></div></div><div v-if="layerOpen" class="space-y-2 mt-3"><USwitch v-model="showGridBoundaries" label="网格边界" size="sm" /><USwitch v-for="layer in mapState.layers" :key="layer.id" :model-value="layer.enabled" :label="layer.name" size="sm" @update:model-value="value=>toggleLayer(layer,!!value)" /><UFormField label="加载深度"><USelect v-model="loadDepth" :items="[{label:'0',value:0},{label:'1',value:1},{label:'2',value:2},{label:'3',value:3},{label:'4',value:4}]" class="w-full" /></UFormField><UButton label="导出地图" icon="i-lucide-download" variant="outline" @click="openExport" /></div><div v-if="query && searchResults" class="map-search-results"><button v-for="item in matches.slice(0,20)" :key="item.id" @click="choose(item)">{{ item.name }}</button><p v-if="!matches.length" class="p-2 text-muted">没有匹配场所</p></div></div>
    <div class="grid-toolbar floating"><GridTreeSelect v-model="filter.grid" allow-all placeholder="选择地图网格" @update:model-value="gridChanged" /></div>
    <UAlert v-if="error" :description="error" color="error" class="map-error" closable @update:open="value=>{if(!value)error=''}" />
    <div v-if="pending" class="map-save floating">
      <strong>{{ editingTarget ? `修改${editingTarget.kind==='grid'?'网格边界':'场所位置'} · ${editingTarget.name}` : pending.type==='Point'?'已标记位置':`已画 ${pending.type==='MultiPolygon'?pending.areas?.length:1} 个区域` }}</strong>
      <div class="flex gap-2 flex-wrap mt-2">
        <UButton v-if="editingTarget" :label="editingTarget.kind==='grid'?'保存网格边界':'保存场所位置'" :loading="saving" :disabled="sketching" @click="saveShape(editingTarget.kind,editingTarget.id,editingTarget.revision)" />
        <template v-else>
          <UButton label="新建场所" icon="i-lucide-plus" :disabled="saving||sketching" @click="newPlace" />
          <template v-if="pending.type!=='Point'">
            <UButton label="新建网格" variant="outline" :disabled="saving||sketching" @click="editingGrid=null;gridEditor=true" />
            <UButton label="更新网格边界" color="neutral" variant="outline" :loading="saving" :disabled="!boundaryTarget||sketching" :title="boundaryTarget?'':'请在上方选择要更新的网格'" @click="saveShape('grid',boundaryTarget,mapState.features.find(x=>x.kind==='grid'&&x.id===boundaryTarget)?.revision??0)" />
          </template>
        </template>
        <UButton label="取消" color="neutral" variant="ghost" :disabled="saving" @click="cancelGeometry" />
      </div>
    </div>
    <div v-if="selected && !pending" class="map-pane-stack" :class="{'has-use':useOpen,'has-inspection':!!inspectionId}">
      <div class="map-mobile-tabs floating"><button :class="{active:mobilePane==='place'}" @click="mobilePane='place'">场所信息</button><button v-if="useOpen" :class="{active:mobilePane==='use'}" @click="mobilePane='use'">使用情况</button><button v-if="inspectionId" :class="{active:mobilePane==='inspection'}" @click="mobilePane='inspection'">排查详情</button><UButton icon="i-lucide-x" aria-label="关闭全部详情" color="neutral" variant="ghost" @click="closePlace" /></div>
      <aside class="map-pane floating" :class="{'mobile-active':mobilePane==='place'}" aria-label="场所信息窗"><header><div><small>{{ selected.kind==='grid'?'网格范围':'场所信息' }}</small><h2>{{ selected.name }}</h2></div><UButton icon="i-lucide-x" aria-label="关闭场所信息" color="neutral" variant="ghost" @click="closePlace" /></header><div class="pane-scroll"><template v-if="detail"><div v-if="detail.photos?.length" class="place-cover"><img :src="`/photos/${detail.photos[0]!.id}?size=thumb`" alt="场所照片" /></div><p>{{ detail.point.address }}</p><p class="text-sm text-muted mt-2">{{ detail.point.communityName }} · {{ detail.point.typeName }}</p><p v-if="detail.point.contact||detail.point.phone" class="text-sm mt-2">{{ detail.point.contact }} {{ detail.point.phone }}</p><div class="flex gap-2 flex-wrap mt-3"><UButton label="修改场所" size="sm" variant="outline" @click="editingPoint=detail.point;editor=true" /><UButton label="修改位置" size="sm" color="neutral" variant="outline" @click="editShape" /><UButton :to="{path:'/inspections/new',query:{pointId:selected.id,returnTo}}" label="登记排查" size="sm" /></div><section class="pane-section"><div class="flex items-center justify-between"><h3>使用情况 <small>{{ shownUses.length }}</small></h3><UButton label="添加" icon="i-lucide-plus" size="sm" variant="ghost" @click="openUse(null)" /></div><UCheckbox v-if="uses.some(x=>x.archived||x.data.state==='已结束')" v-model="showEnded" label="包括已结束" class="my-2" /><button v-for="item in shownUses" :key="item.id" class="pane-record" :class="{active:useOpen&&useId===item.id}" @click="openUse(item)"><span class="text-2xl">{{ purpose(item.data.purposeId)?.data.icon }}</span><span class="flex-1"><strong>{{ item.name }}</strong><small>{{ item.data.position }} · {{ purpose(item.data.purposeId)?.name }} · {{ item.data.state }}</small></span><UIcon name="i-lucide-chevron-right" /></button><p v-if="!shownUses.length" class="text-sm text-muted py-3">尚未登记使用情况</p></section><section class="pane-section"><h3>排查概览 <small v-if="detail.inspections.length">{{ detail.inspections.length }} 次<span v-if="detail.openIssues.length"> · {{ detail.openIssues.length }} 项待完成</span></small></h3><button v-for="check in detail.inspections" :key="check.id" class="pane-record" :class="{active:inspectionId===check.id}" @click="inspectionId=check.id;mobilePane='inspection'"><span class="flex-1"><strong>{{ check.inspectionTypeName||'日常检查' }}</strong><small>{{ check.date }} · {{ check.useName||'整个场所' }} · {{ check.inspector }}</small></span><UBadge :color="check.result==='normal'?'success':check.result==='incomplete'?'neutral':check.openIssueCount?'warning':'success'" variant="subtle">{{ check.result==='normal'?'正常':check.result==='incomplete'?'未完成':check.openIssueCount?`${check.openIssueCount} 项待办`:'已完成' }}</UBadge></button><p v-if="!detail.inspections.length" class="text-sm text-muted py-3">暂无排查记录</p></section></template><template v-else-if="selected.kind==='grid'"><div class="flex gap-2"><UButton label="修改网格边界" variant="outline" @click="editShape" /><UButton label="网格设置" variant="outline" @click="editingGrid=bootstrap?.communities.find(x=>x.id===selected?.id)??null;gridEditor=true" /></div></template><p v-else class="text-muted">正在读取场所…</p></div></aside>
      <aside v-if="useOpen&&detail" class="map-pane floating" :class="{'mobile-active':mobilePane==='use'}" aria-label="使用情况窗"><header><div><small>{{ detail.point.name }}</small><h2>{{ currentUse?'使用情况':'添加使用情况' }}</h2></div><UButton icon="i-lucide-x" aria-label="关闭使用情况" color="neutral" variant="ghost" @click="closeUse" /></header><div class="pane-scroll"><UseDetailPanel :return-to="returnTo" ref="usePanel" :key="useId||'new'" :point-id="detail.point.id" :record="currentUse" @saved="useSaved" @cancel="useOpen=false;mobilePane='place'" /></div></aside>
      <aside v-if="inspectionId" class="map-pane floating" :class="{'mobile-active':mobilePane==='inspection'}" aria-label="排查详情窗"><header><h2>排查详情</h2><UButton icon="i-lucide-x" aria-label="关闭排查详情" color="neutral" variant="ghost" @click="inspectionId='';mobilePane='place'" /></header><div class="pane-scroll"><MapInspectionPanel :return-to="returnTo" :id="inspectionId" @changed="refreshed" /></div></aside>
    </div>

    <GridEditor v-model:open="gridEditor" :record="editingGrid" :shape="pending" :initial-parent-id="filter.grid==='all'?'':filter.grid" @saved="gridCreated" />
    <PointEditor v-model:open="editor" :point="editingPoint" :initial-coordinates="pendingCoordinates" :initial-shape="pending" @saved="created" />
    <UModal v-model:open="exportOpen" title="导出地图" :dismissible="!exporting" :close="!exporting">
      <template #body><div class="space-y-3">
        <div class="field-grid"><UFormField label="倍率"><UInput v-model.number="exportScale" type="number" min="1" max="8" step="1" class="w-full" :disabled="exporting" /></UFormField><UFormField label="分区"><UInput v-model.number="exportPartitions" type="number" min="1" max="8" step="1" class="w-full" :disabled="exporting" /></UFormField></div>
        <p>分辨率：{{ exportResolution[0] }} × {{ exportResolution[1] }}</p>
        <div class="space-y-2"><UCheckbox v-for="layer in mapState.layers" :key="layer.id" :model-value="exportLayerIds.includes(layer.id)" :label="layer.name" :disabled="exporting" @update:model-value="value=>toggleExportLayer(layer.id,!!value)" /></div>
        <div class="space-y-2"><UCheckbox v-model="exportAll" label="全部场所（忽略当前筛选）" :disabled="exporting" /><p data-testid="map-export-count" class="text-sm text-muted">将导出 {{ exportPointCount }} 个场所{{ exportAll?'（全部）':'（当前筛选）' }}</p></div><div class="flex flex-wrap gap-4"><UCheckbox v-model="exportMarkers" label="场所标记" :disabled="exporting" /><UCheckbox v-model="exportGrids" label="网格区域" :disabled="exporting" /></div>
        <UAlert v-if="exportError" :description="exportError" color="error" />
      </div></template>
      <template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="exporting" @click="exportOpen=false" /><UButton label="导出 PNG" :loading="exporting" @click="exportMap" /></template>
    </UModal>
  </div>
</template>
